    const po=(b.match(/\(/g)||[]).length, pc=(b.match(/\)/g)||[]).length;
    console.log('  block '+i+': [ ]='+open+'/'+close+'  ( )='+po+'/'+pc+'  firstline='+b.split('\n')[0]);
